// EDIT ME. projects: [{tag, id, pages, shots}]; langs for filter_langs; glossary cursor ('' = first page)
const B = 'https://api.lokalise.com/api2/projects/';
const projects = [ { tag: 'vin', id: '2944050668d5010cbd95e8.36175908', pages: [1,2,3,4,5], shots: false } ];
const langs = 'en,es';
const glossary = { id: '46552447679363c70f7ef8.58193285', cursor: '' };
const out = [];
for (const p of projects) {
  for (const n of p.pages) { out.push({ json: { kind: 'keys', tag: p.tag, url: B + p.id + '/keys?include_translations=1&filter_langs=' + langs + (p.shots ? '&include_screenshots=1' : '') + '&limit=500&page=' + n } }); }
  if (p.shots) { out.push({ json: { kind: 'shots', tag: p.tag, url: B + p.id + '/screenshots?limit=500' } }); }
}
out.push({ json: { kind: 'glossary', tag: 'g', url: B + glossary.id + '/glossary-terms?limit=500' + (glossary.cursor ? '&cursor=' + glossary.cursor : '') } });
return out;

const rq = $('Config').all(); const res = $input.all();
const R = { vin: [], rc: [], shots: [], glossary: [], glossary_next_cursor: null, status: [] };
for (let i = 0; i < res.length; i++) {
  const q = rq[i].json; const r = res[i].json; const b = r.body || {}; const h = r.headers || {};
  R.status.push(q.kind + ':' + q.tag + ':' + r.statusCode + ':' + (h['x-pagination-total-count'] || ''));
  if (q.kind === 'keys') {
    for (const k of (b.keys || [])) {
      if (k.is_archived) { continue; }
      const o = { id: k.key_id, name: (k.key_name && k.key_name.web) || k.key_name, plural: k.is_plural, desc: k.description || '', tags: k.tags || [], created_at: k.created_at };
      for (const t of (k.translations || [])) { const iso = (t.language_iso || '').toLowerCase(); if (iso === 'en') { o.en = t.translation; } if (iso === 'es') { o.es = t.translation; o.es_by = t.modified_by_email; o.es_rev = t.is_reviewed; o.es_tid = t.translation_id; } }
      if (q.tag === 'vin') { o.shots = (k.screenshots || []).map(function (s) { return s.screenshot_id; }); R.vin.push(o); } else if (o.es) { R.rc.push({ name: o.name, en: o.en, es: o.es }); }
    }
  } else if (q.kind === 'shots') {
    for (const s of (b.screenshots || [])) { R.shots.push({ id: s.screenshot_id, title: s.title, description: s.description, keys: (s.key_ids || []).length, key_ids: s.key_ids, w: s.width, h: s.height, url: s.url, tags: s.tags }); }
  } else {
    R.glossary_next_cursor = h['x-pagination-next-cursor'] || null;
    for (const g of (b.data || [])) { const es = (g.translations || []).filter(function (t) { return t.langId === 1056; })[0]; R.glossary.push({ term: g.term, desc: g.description, tags: g.tags, translatable: g.translatable, forbidden: g.forbidden, cs: g.caseSensitive, es: es ? es.translation : '', es_desc: es ? es.description : '' }); }
  }
}
return [{ json: R }];
